    action: str,
    conversation: ConversationState,
    reason: str,
    queue: str | None = None,
    guardrail: GuardrailOutcome | None = None,
) -> dict[str, object]:
    event = {
        "action": action,
        "conversation_id": conversation.conversation_id,
        "case_id": conversation.case_id,
        "customer_id": conversation.customer_id,
        "queue_name": queue,
        "reason": reason,
        "escalation_intent": conversation.escalation_intent,
    }
    if guardrail is not None:
        event["guardrail_reason"] = guardrail.reason
        event["policy_id"] = guardrail.policy_id
        event["blocked_action"] = guardrail.blocked_action
    return event


def unique_audit_events(handoffs: list[dict[str, object]]) -> list[dict[str, object]]:
    seen_conversations: set[str] = set()
    events: list[dict[str, object]] = []
    for handoff in handoffs:
        conversation_id = str(handoff["conversation_id"])
        if conversation_id in seen_conversations:
            continue
        seen_conversations.add(conversation_id)
        for event in handoff["audit_events"]:  # type: ignore[index]
            events.append(event)
    return events


