from __future__ import annotations

from handoff_models import CaseSnapshot, ConversationState, SENSITIVE_FIELD_NAMES


DEFAULT_CASE_PRIORITY = "Medium"
DEFAULT_CASE_STATUS = "Open"


def normalize_priority(priority: str | None) -> str:
    if priority is None:
        return DEFAULT_CASE_PRIORITY
    cleaned = priority.strip().title()
    if cleaned in {"Low", "Medium", "High", "Critical"}:
        return cleaned
    return DEFAULT_CASE_PRIORITY


def sensitive_field_count(case: CaseSnapshot) -> int:
    count = 0
    for field_name in case.sensitive_fields:
        if field_name.strip().lower() in SENSITIVE_FIELD_NAMES:
            count += 1
    return count


def fallback_case_for(conversation: ConversationState) -> CaseSnapshot:
    return CaseSnapshot(
        case_id=conversation.case_id,
        customer_id=conversation.customer_id,
        subject="Case context unavailable",
        status=DEFAULT_CASE_STATUS,
        priority=DEFAULT_CASE_PRIORITY,
        entitlement="standard",
        open_minutes=0,
        sensitive_fields=(),
    )


class CaseRegistry:
    def __init__(self, cases: list[CaseSnapshot] | None = None) -> None:
        self._cases = list(cases or [])

    def find_for(self, conversation: ConversationState) -> CaseSnapshot | None:
        for case in self._cases:
            if case.case_id != conversation.case_id:
                continue
            if case.customer_id != conversation.customer_id:
                continue
            return case
        return None

    def required_for(self, conversation: ConversationState) -> CaseSnapshot:
        case = self.find_for(conversation)
        if case is None:
            return fallback_case_for(conversation)
        return case

    def priority_for(self, conversation: ConversationState) -> str:
        case = self.find_for(conversation)
        if case is None:
            return DEFAULT_CASE_PRIORITY
        return normalize_priority(case.priority)

    def redacted_field_count_for(self, conversation: ConversationState) -> int:
        case = self.find_for(conversation)
        if case is None:
            return 0
        return sensitive_field_count(case)

    def open_case_ids_for_customer(self, customer_id: str) -> tuple[str, ...]:
        case_ids: list[str] = []
        for case in self._cases:
            if case.customer_id == customer_id and case.status in {"New", "Open", "Working", "Escalated"}:
                case_ids.append(case.case_id)
        return tuple(case_ids)

