from __future__ import annotations


class HandoffStore:
    def __init__(self, seed: dict[str, dict[str, object]] | None = None) -> None:
        self._by_conversation: dict[str, dict[str, object]] = dict(seed or {})

    def get(self, conversation_id: str) -> dict[str, object] | None:
        return self._by_conversation.get(conversation_id)

    def save(self, handoff: dict[str, object]) -> dict[str, object]:
        conversation_id = str(handoff["conversation_id"])
        self._by_conversation[conversation_id] = handoff
        return handoff

    def upsert(self, handoff: dict[str, object]) -> dict[str, object]:
        conversation_id = str(handoff["conversation_id"])
        existing = self._by_conversation.get(conversation_id)
        if existing is not None:
            return existing
        self._by_conversation[conversation_id] = handoff
        return handoff

    def all_handoffs(self) -> list[dict[str, object]]:
        return list(self._by_conversation.values())

    def count(self) -> int:
        return len(self._by_conversation)

    def contains(self, conversation_id: str) -> bool:
        return conversation_id in self._by_conversation

    def remove(self, conversation_id: str) -> dict[str, object] | None:
        return self._by_conversation.pop(conversation_id, None)

    def as_dict(self) -> dict[str, dict[str, object]]:
        return dict(self._by_conversation)

    def created_count(self) -> int:
        return sum(1 for handoff in self._by_conversation.values() if handoff["status"] == "created")

    def rejected_count(self) -> int:
        return sum(1 for handoff in self._by_conversation.values() if handoff["status"] == "rejected")

    def snapshot(self) -> dict[str, object]:
        return {
            "conversation_count": self.count(),
            "created_count": self.created_count(),
            "rejected_count": self.rejected_count(),
            "conversation_ids": sorted(self._by_conversation),
        }


def store_from_prior(prior_handoffs: dict[str, dict[str, object]] | None) -> HandoffStore:
    return HandoffStore(prior_handoffs)


def copy_store_back(store: HandoffStore, target: dict[str, dict[str, object]] | None) -> None:
    if target is None:
        return
    target.clear()
    target.update(store.as_dict())


def merge_handoff_stores(primary: HandoffStore, secondary: HandoffStore) -> HandoffStore:
    merged = HandoffStore(primary.as_dict())
    for handoff in secondary.all_handoffs():
        merged.upsert(handoff)
    return merged

