from __future__ import annotations

from context_builder import context_to_public_dict


def handoff_to_dict(package: dict[str, object]) -> dict[str, object]:
    context = package.get("context")
    if context is not None and not isinstance(context, dict):
        context = context_to_public_dict(context)  # type: ignore[arg-type]

    return {
        "status": package["status"],
        "handoff_id": package["handoff_id"],
        "conversation_id": package["conversation_id"],
        "case_id": package["case_id"],
        "customer_id": package["customer_id"],
        "queue_name": package["queue_name"],
        "verified_channel": package["verified_channel"],
        "last_safe_summary": package["last_safe_summary"],
        "escalation_intent": package["escalation_intent"],
        "guardrail_reason": package["guardrail_reason"],
        "blocked_action": package["blocked_action"],
        "policy_id": package["policy_id"],
        "policy_version": package.get("policy_version"),
        "context": context,
        "audit_events": package["audit_events"],
    }


def public_handoff_summary(handoff: dict[str, object]) -> dict[str, object]:
    return {
        "handoff_id": handoff["handoff_id"],
        "conversation_id": handoff["conversation_id"],
        "case_id": handoff["case_id"],
        "queue_name": handoff["queue_name"],
        "status": handoff["status"],
        "guardrail_reason": handoff["guardrail_reason"],
    }


def serialize_handoff_list(handoffs: list[dict[str, object]]) -> list[dict[str, object]]:
    return [handoff_to_dict(handoff) for handoff in handoffs]


def status_counts(handoffs: list[dict[str, object]]) -> dict[str, int]:
    counts = {"created": 0, "rejected": 0}
    for handoff in handoffs:
        status = str(handoff["status"])
        if status in counts:
            counts[status] += 1
    return counts


def queue_counts(handoffs: list[dict[str, object]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for handoff in handoffs:
        queue_name = handoff.get("queue_name")
        if queue_name is None:
            continue
        queue_key = str(queue_name)
        counts[queue_key] = counts.get(queue_key, 0) + 1
    return counts


def package_contains_guardrail_context(handoff: dict[str, object]) -> bool:
    return bool(handoff.get("guardrail_reason") and handoff.get("policy_id"))

