from __future__ import annotations

from case_registry import CaseRegistry
from handoff_models import CaseSnapshot, ConversationState, GuardrailOutcome, HandoffRoutingRule


PRIORITY_RANK = {
    "Low": 0,
    "Medium": 1,
    "High": 2,
    "Critical": 3,
}


def _priority_at_least(actual: str, minimum: str | None) -> bool:
    if minimum is None:
        return True
    return PRIORITY_RANK.get(actual, 0) >= PRIORITY_RANK.get(minimum, 0)


def _case_priority(conversation: ConversationState, cases: list[CaseSnapshot] | None) -> str:
    return CaseRegistry(cases).priority_for(conversation)


def _rule_score(
    rule: HandoffRoutingRule,
    conversation: ConversationState,
    guardrail: GuardrailOutcome,
    case_priority: str,
) -> int | None:
    if rule.escalation_intent != conversation.escalation_intent:
        return None
    if rule.customer_tier != conversation.customer_tier:
        return None
    if rule.requires_verified_channel and conversation.verified_channel is None:
        return None
    if rule.guardrail_reason is not None and rule.guardrail_reason != guardrail.reason:
        return None
    if not _priority_at_least(case_priority, rule.min_case_priority):
        return None

    score = 0
    if rule.guardrail_reason is not None:
        score += 10
    if rule.min_case_priority is not None:
        score += 3
    if rule.requires_verified_channel:
        score += 1
    return score


def choose_handoff_queue(
    conversation: ConversationState,
    guardrail: GuardrailOutcome,
    rules: list[HandoffRoutingRule],
    cases: list[CaseSnapshot] | None = None,
) -> str:
    case_priority = _case_priority(conversation, cases)
    best: tuple[int, int, HandoffRoutingRule] | None = None
    for index, rule in enumerate(rules):
        score = _rule_score(rule, conversation, guardrail, case_priority)
        if score is None:
            continue
        candidate = (score, -index, rule)
        if best is None or candidate > best:
            best = candidate

    if best is None:
        return "general-support"
    return best[2].queue_name


def explain_routing(
    queue_name: str,
    conversation: ConversationState,
    guardrail: GuardrailOutcome,
) -> dict[str, object]:
    return {
        "queue_name": queue_name,
        "conversation_id": conversation.conversation_id,
        "case_id": conversation.case_id,
        "escalation_intent": conversation.escalation_intent,
        "customer_tier": conversation.customer_tier,
        "guardrail_reason": guardrail.reason,
        "decision": "default_route" if queue_name == "general-support" else "matched_route",
    }


def candidate_routes(
    conversation: ConversationState,
    guardrail: GuardrailOutcome,
    rules: list[HandoffRoutingRule],
    cases: list[CaseSnapshot] | None = None,
) -> list[dict[str, object]]:
    case_priority = _case_priority(conversation, cases)
    candidates: list[dict[str, object]] = []
    for index, rule in enumerate(rules):
        score = _rule_score(rule, conversation, guardrail, case_priority)
        if score is None:
            continue
        candidates.append(
            {
                "queue_name": rule.queue_name,
                "score": score,
                "rule_index": index,
                "guardrail_reason": rule.guardrail_reason,
                "min_case_priority": rule.min_case_priority,
            }
        )
    return candidates


def route_health_snapshot(rules: list[HandoffRoutingRule]) -> dict[str, object]:
    queue_names = {rule.queue_name for rule in rules}
    verified_only = sum(1 for rule in rules if rule.requires_verified_channel)
    reason_specific = sum(1 for rule in rules if rule.guardrail_reason is not None)
    return {
        "rule_count": len(rules),
        "queue_count": len(queue_names),
        "verified_only_rule_count": verified_only,
        "reason_specific_rule_count": reason_specific,
    }


class HandoffRouter:
    def __init__(self, rules: list[HandoffRoutingRule]) -> None:
        self.rules = list(rules)

    def route(
        self,
        conversation: ConversationState,
        guardrail: GuardrailOutcome,
        cases: list[CaseSnapshot] | None = None,
    ) -> dict[str, object]:
        queue = choose_handoff_queue(conversation, guardrail, self.rules, cases)
        return explain_routing(queue, conversation, guardrail)

    def candidates(
        self,
        conversation: ConversationState,
        guardrail: GuardrailOutcome,
        cases: list[CaseSnapshot] | None = None,
    ) -> list[dict[str, object]]:
        return candidate_routes(conversation, guardrail, self.rules, cases)

    def health(self) -> dict[str, object]:
        return route_health_snapshot(self.rules)

