from __future__ import annotations

from handoff_models import ConversationState, GuardrailOutcome


HIGH_RISK_REASONS = {"legal_dispute", "regulated_advice", "identity_mismatch"}
CUSTOMER_REQUEST_REASONS = {"customer_requested_human", "agent_requested_human"}


def requires_human_handoff(guardrail: GuardrailOutcome) -> bool:
    if guardrail.decision == "block":
        return True
    return guardrail.reason in CUSTOMER_REQUEST_REASONS


def handoff_risk_level(guardrail: GuardrailOutcome) -> str:
    if guardrail.reason in HIGH_RISK_REASONS:
        return "high"
    if guardrail.decision == "block":
        return guardrail.severity
    return "normal"


def validate_handoff_request(conversation: ConversationState, guardrail: GuardrailOutcome) -> list[str]:
    problems: list[str] = []
    if conversation.verified_channel is None:
        problems.append("missing_verified_channel")
    if not requires_human_handoff(guardrail):
        problems.append("handoff_not_required")
    if guardrail.decision == "block" and guardrail.policy_id is None:
        problems.append("missing_policy_id")
    return problems


def trust_context(conversation: ConversationState, guardrail: GuardrailOutcome) -> dict[str, object]:
    return {
        "conversation_id": conversation.conversation_id,
        "case_id": conversation.case_id,
        "requires_handoff": requires_human_handoff(guardrail),
        "risk_level": handoff_risk_level(guardrail),
        "guardrail_reason": guardrail.reason,
        "blocked_action": guardrail.blocked_action,
        "policy_id": guardrail.policy_id,
        "policy_version": guardrail.policy_version,
    }


def rejection_reason(problems: list[str]) -> str:
    if not problems:
        return "none"
    if "missing_verified_channel" in problems:
        return "missing_verified_channel"
    if "handoff_not_required" in problems:
        return "handoff_not_required"
    return problems[0]


def guardrail_audit_label(guardrail: GuardrailOutcome) -> str:
    if guardrail.policy_id is None:
        return f"{guardrail.decision}:{guardrail.reason}"
    return f"{guardrail.decision}:{guardrail.reason}:{guardrail.policy_id}"


def can_show_blocked_action_to_agent(guardrail: GuardrailOutcome) -> bool:
    return guardrail.decision == "block" and guardrail.blocked_action is not None

